import logging
from taf.analyzer.pdml import PdmlReader
from taf.ul.parser.pcap.converter import Converter
from taf.ul.parser.pcap.filter import Filter
from taf.ul.parser.pcap.expression_parser import ExpressionParser
from taf.ul.parser.pcap.exceptions import DuplicatedFieldError


class PcapParser(object):
    @staticmethod
    def convert_pcap_file(pcap_file, tshark_path=None, luashark_path=None, command_template=None):
        return Converter().convert_pcap_to_pdml(pcap_file, tshark_path, luashark_path, command_template)

    @staticmethod
    def read_pdml_file(pdml_file):
        with open(pdml_file, "rb") as file_obj:
            try:
                for pdml_entry in PdmlReader(file_obj=file_obj):
                    yield pdml_entry
            except Exception as e:
                logging.error("PdmlReader failure: {}".format(e))

    @staticmethod
    def filter_packets_by_expression(pdml_entries, filter_expression):
        logic_expression, field_expressions = ExpressionParser().parse(filter_expression)
        packet_filter = Filter(logic_expression, field_expressions)
        for pdml_entry in pdml_entries:
            if packet_filter.is_packet_matched(pdml_entry.packet):
                yield pdml_entry

    def get_field_value_by_name(self, pdml_entries, field_name, attribute_name="show"):
        field_values = []
        for pdml_entry in pdml_entries:
            packet = pdml_entry.packet
            field_regex = "{}$".format(field_name)
            field_found_count = len(packet.findall(field_regex))
            if field_found_count > 1:
                xpath_regex = ".*/{name}$".format(name=field_name)
                field_xpath_list = packet.paths(xpath_regex)
                xpaths = [".//{}".format(xpath) for xpath in
                          self._find_xpaths_for_same_field_name(field_xpath_list, field_name)]
                raise DuplicatedFieldError(field_name,
                                           "Please use get_field_value_by_xpath. Referenced xpaths:{}".format(xpaths))
            elif field_found_count == 1:
                field_values.append(getattr(packet[field_regex], attribute_name))
        return field_values

    @staticmethod
    def get_field_value_by_xpath(pdml_entries, xpath, attribute_name="show"):
        field_values = []
        for pdml_entry in pdml_entries:
            packet = pdml_entry.packet
            field_values.extend(packet.xpath(xpath))
        return [getattr(field, attribute_name) for field in field_values]

    def _find_xpaths_for_same_field_name(self, field_xpaths, xpath_ref):
        xpath_ref_list = []
        for xpath in field_xpaths:
            offset = - (len(xpath_ref) + 1)
            index = xpath.rfind('/', 0, offset)
            new_xpath_ref = xpath[index + 1:]
            if new_xpath_ref not in xpath_ref_list:
                xpath_ref_list.append(new_xpath_ref)
            else:
                return self._find_xpaths_for_same_field_name(field_xpaths, new_xpath_ref)
        return xpath_ref_list
